mapper.select:
select t.*, u.avatar, u.user_name as userName, g.game_name as gameName, g.game_img as gameImg, fot.content as fastContent, fot.voice as fastVoice, fot.sec as fastSec, u.sex, u.age, (select ifnull(avg(score),0) from taking_commnt where order_taking_id=t.id) as commentScore, (select count(*) from taking_commnt where order_taking_id=t.id) as commentCount, (select count(*) from orders where order_taking_id=t.id) as ordersCount from order_taking t LEFT JOIN game g ON t.game_id = g.id LEFT JOIN tb_user u ON u.user_id = t.user_id left join fast_order_take fot on fot.user_id=u.user_id where t.status=0
and t.game_id=#{fastOrder.gameId}
and t.user_id in (select user_id from tb_user where sex=#{fastOrder.sex})
and t.money>=#{fastOrder.minMoney}
and t.money<=#{fastOrder.maxMoney}
and t.order_level like concat('%',#{fastOrder.orderLevel},'%')
and left(t.order_taking_time,5)<=DATE_FORMAT(#{fastOrder.orderTakingTime},'%H:%i') and right(t.order_taking_time,5)>=DATE_FORMAT(#{fastOrder.orderTakingTime},'%H:%i')
